        neighbors = random.sample(nodes[:node] + nodes[node+1:], d)
        for neighbor in neighbors:
            edge = tuple(sorted((node, neighbor)))
            if edge not in edges and (neighbor, node) not in edges:
                edges.add(edge)
    return edges

