        clause = [variables[f"x{i}"]]
        for j in range(i+1, n):
            if (i, j) not in graph and (j, i) not in graph:
                clause.append(-variables[f"x{j}"])
            elif (i, j) in graph or (j, i) in graph:
                clause.append(variables[f"x{j}"])
        clauses.append(clause)
    return clauses

